// FakeDb.java — a tiny stand-in that "interprets" SQL to show the attack effect
package com.nbi.db;

import java.util.*;

public class FakeDb {
    // account table: id -> balance
    private final Map<String,Double> accounts = new LinkedHashMap<>(Map.of(
        "A100", 50000.0, "A200", 2000.0, "A300", 99999.0));

    // VULNERABLE: executes a fully-built SQL string (structure can be changed by input).
    public List<String> executeRaw(String sql) {
        List<String> out = new ArrayList<>();
        // Simulate the engine: a tautology like OR '1'='1' matches every row.
        if (sql.contains("OR '1'='1'")) {
            accounts.forEach((id,bal) -> out.add(id + "=" + bal)); // ALL rows leaked!
            return out;
        }
        // otherwise parse the literal id after id='
        String marker = "id='";
        int i = sql.indexOf(marker);
        if (i >= 0) {
            String id = sql.substring(i + marker.length(), sql.indexOf("'", i + marker.length()));
            if (accounts.containsKey(id)) out.add(id + "=" + accounts.get(id));
        }
        return out;
    }

    // SAFE: value is bound as data, never parsed as SQL (structure fixed).
    public List<String> executeParameterized(String sqlWithPlaceholder, String boundValue) {
        List<String> out = new ArrayList<>();
        // The bound value is ONLY ever a literal id — no interpretation as SQL.
        if (accounts.containsKey(boundValue)) out.add(boundValue + "=" + accounts.get(boundValue));
        return out;
    }
}
