// AccountLookup.java — vulnerable vs safe lookup methods
package com.nbi.db;

import java.util.List;

public class AccountLookup {
    private final FakeDb db;
    public AccountLookup(FakeDb db) { this.db = db; }

    // BAD: string concatenation -> SQL injection.
    public List<String> findVulnerable(String accountId) {
        String sql = "SELECT id, balance FROM accounts WHERE id='" + accountId + "'";
        return db.executeRaw(sql);
    }

    // GOOD: parameterized -> input bound as a value (PreparedStatement style).
    public List<String> findSafe(String accountId) {
        String sql = "SELECT id, balance FROM accounts WHERE id = ?"; // placeholder
        return db.executeParameterized(sql, accountId);               // bind value
    }
}
