// Demo.java — same malicious payload against both paths
package com.nbi.db;

import java.util.List;

public class Demo {
    public static void main(String[] args) {
        AccountLookup lookup = new AccountLookup(new FakeDb());

        String legit = "A100";
        String attack = "' OR '1'='1";

        System.out.println("VULNERABLE path:");
        System.out.println("  legit  'A100'        -> " + lookup.findVulnerable(legit));
        System.out.println("  attack \"' OR '1'='1\" -> " + lookup.findVulnerable(attack)
                + "   <- ALL accounts leaked!");

        System.out.println("SAFE (parameterized) path:");
        System.out.println("  legit  'A100'        -> " + lookup.findSafe(legit));
        System.out.println("  attack \"' OR '1'='1\" -> " + lookup.findSafe(attack)
                + "   <- treated as a literal id, matches nothing");
    }
}
